const sourceFileId=String(j.id||j.fileId||'').trim();
if(!sourceFileId) throw new Error('Google Drive file ID missing.');
return [{json:{...j,sourceFileId,sourceFileName:String(j.name||'unknown')}}];

const j=$json;
const risky=j.needsHumanApproval?'YES':'NO';
return [{json:{...j,securityNote:j.injectionDetected?'Prompt-injection text detected; treat email as untrusted data.':'No known prompt-injection pattern detected.',approvalNote:risky==='YES'?'Human approval required due to sensitivity or injection pattern.':'Still verify source and confidence before any automatic send.'}}];

// Auto-send everything EXCEPT prompt-injection emails (those still need owner approval).
// Payment/refund emails never reach here: the classifier sends them to the owner-only branch.
const autoSendEligible = !$json.injectionDetected;
return [{ json: { ...$json, autoSendEligible } }];

const j=$json;
const email=String(j.body||'');
const masked=email.replace(/([A-Z0-9._%+-]+)@([A-Z0-9.-]+\.[A-Z]{2,})/gi,'[EMAIL_REDACTED]').replace(/\b(?:\d[ -]*?){13,19}\b/g,'[CARD_REDACTED]').replace(/\b(?:password|api[_ -]?key|token)\s*[:=]\s*\S+/gi,'[SECRET_REDACTED]');
return [{json:{...j,bodyForLogs:masked,piiMasked:true,logPolicy:'Do not store full email body or credentials in logs.'}}];

// Classify the REAL email (subject + body), not the summary of the headers.
const g = $('Security + Duplicate Guard').first().json;
const out = $json.output;
const summary = typeof out === 'string' ? out : (out?.text || '');
const textToClassify = `Subject: ${g.subject}\n\n${g.body}`.trim();
if (!g.body) throw new Error('Email body is empty; stopping before classification.');
return [{ json: { ...$json, summary, textToClassify } }];

// Cleans up the AI draft so it is email-ready.
const AGENT = 'Company info agent';
const CATEGORY = 'Company info request';
const SIGN_OFF = 'Best regards,\nCustomer Support Team';

let t = String($json.output ?? $json.text ?? '').trim();
if (!t) throw new Error(`${AGENT}: the AI returned an empty draft.`);

t = t.replace(/\r\n/g, '\n')
  .replace(/```[a-z]*\n?|```/gi, '')                 // code fences
  .replace(/^\s*subject\s*:.*\n+/i, '')              // "Subject:" line (Gmail keeps the thread subject)
  .replace(/\*\*(.*?)\*\*/g, '$1')                   // **bold**
  .replace(/^#{1,6}\s*/gm, '')                       // # headings
  .replace(/(dear|hi|hello)\s+\[[^\]]*\]/gi, 'Hello') // "Dear [Customer Name]"
  .replace(/\[(your name|your company|company name|name|customer name|insert[^\]]*)\]/gi, '')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// remove any sign-off the model wrote, then add one standard sign-off
t = t.replace(/\n+\s*(best regards|kind regards|warm regards|regards|sincerely)\s*[,!]?\s*\n[\s\S]*$/i, '').trim();

return [{ json: { ...$json, output: `${t}\n\n${SIGN_OFF}`, agent: AGENT, category: CATEGORY, polished: true } }];

