const r = $input.first().json;
const n = v => Number(v || 0);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let cats = r.by_category;
if (typeof cats === 'string') { try { cats = JSON.parse(cats); } catch (e) { cats = []; } }
cats = Array.isArray(cats) ? cats : [];

const date = new Date().toLocaleDateString('en-GB', { timeZone: 'Asia/Dhaka', day: '2-digit', month: 'short', year: 'numeric' });
const reportDate = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Dhaka' });

const total = n(r.total_emails);
const replied = n(r.replied);
const pending = n(r.awaiting_approval);
const errors = n(r.errors);
const replyRate = total > 0 ? Math.round((replied / total) * 100) : 0;

// ---- status banner
let banner;
if (errors > 0) {
  banner = { bg: '#fef2f2', border: '#fecaca', color: '#b91c1c', text: `${errors} system error${errors > 1 ? 's' : ''} in the last 24 hours. Please check Slack or the error log.` };
} else if (pending > 0) {
  banner = { bg: '#fffbeb', border: '#fde68a', color: '#b45309', text: `${pending} repl${pending > 1 ? 'ies are' : 'y is'} waiting for your approval.` };
} else {
  banner = { bg: '#f0fdf4', border: '#bbf7d0', color: '#15803d', text: 'All good. No errors and nothing waiting for approval.' };
}

// ---- helpers
const card = (label, value, color) => `
  <td width="33%" style="padding:0 6px">
    <table width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px">
      <tr><td align="center" style="padding:16px 8px">
        <div style="font-size:30px;font-weight:700;color:${color};line-height:1">${value}</div>
        <div style="font-size:12px;color:#64748b;margin-top:6px;text-transform:uppercase;letter-spacing:.5px">${label}</div>
      </td></tr>
    </table>
  </td>`;

const row = (label, value, strong) => `
  <tr>
    <td style="padding:10px 0;border-bottom:1px solid #f1f5f9;font-size:14px;color:#334155">${label}</td>
    <td align="right" style="padding:10px 0;border-bottom:1px solid #f1f5f9;font-size:14px;color:#0f172a;font-weight:${strong ? 700 : 600}">${value}</td>
  </tr>`;

const section = (title, inner) => `
  <tr><td style="padding:24px 32px 0">
    <div style="font-size:13px;font-weight:700;color:#4f46e5;text-transform:uppercase;letter-spacing:.8px;margin-bottom:6px">${title}</div>
    <table width="100%" cellpadding="0" cellspacing="0">${inner}</table>
  </td></tr>`;

const maxCat = Math.max(1, ...cats.map(c => n(c.n)));
const catRows = cats.length
  ? cats.map(c => {
      const pct = Math.max(4, Math.round((n(c.n) / maxCat) * 100));
      return `
      <tr><td colspan="2" style="padding:8px 0;border-bottom:1px solid #f1f5f9">
        <table width="100%" cellpadding="0" cellspacing="0"><tr>
          <td style="font-size:14px;color:#334155">${esc(c.category)}</td>
          <td align="right" style="font-size:14px;font-weight:700;color:#0f172a">${n(c.n)}</td>
        </tr></table>
        <div style="background:#e5e7eb;border-radius:4px;margin-top:6px">
          <div style="width:${pct}%;background:#6366f1;height:6px;border-radius:4px"></div>
        </div>
      </td></tr>`;
    }).join('')
  : `<tr><td style="padding:12px 0;font-size:14px;color:#94a3b8">No emails in the last 24 hours</td></tr>`;

const html = `<!DOCTYPE html>
<html><body style="margin:0;padding:0;background:#f1f5f9">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:24px 0">
<tr><td align="center">
  <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;font-family:Arial,Helvetica,sans-serif">

    <tr><td style="background:#4f46e5;padding:28px 32px">
      <div style="font-size:12px;color:#c7d2fe;text-transform:uppercase;letter-spacing:1px">Daily Report</div>
      <div style="font-size:24px;font-weight:700;color:#ffffff;margin-top:4px">AI Email Assistant</div>
      <div style="font-size:13px;color:#e0e7ff;margin-top:6px">${date} &middot; last 24 hours</div>
    </td></tr>

    <tr><td style="padding:20px 32px 0">
      <div style="background:${banner.bg};border:1px solid ${banner.border};color:${banner.color};border-radius:10px;padding:12px 16px;font-size:14px;font-weight:600">${banner.text}</div>
    </td></tr>

    <tr><td style="padding:20px 26px 0">
      <table width="100%" cellpadding="0" cellspacing="0"><tr>
        ${card('Received', total, '#0f172a')}
        ${card('Replied', replied, '#16a34a')}
        ${card('Pending', pending, pending > 0 ? '#d97706' : '#64748b')}
      </tr></table>
    </td></tr>

    ${section('Emails', `
      ${row('Reply rate', replyRate + '%', true)}
      ${row('Approved &amp; sent', replied)}
      ${row('Waiting for your approval', pending)}
      ${row('Rejected by you', n(r.rejected))}
      ${row('Payment / refund (owner only)', n(r.owner_only))}
    `)}

    ${section('Meetings', `
      ${row('Booked', n(r.bookings_made))}
      ${row('Rescheduled', n(r.bookings_rescheduled))}
      ${row('Cancelled', n(r.bookings_cancelled))}
    `)}

    ${section('By category', catRows)}

    ${section('System health', row('Errors', errors, errors > 0))}

    <tr><td style="padding:28px 32px">
      <div style="border-top:1px solid #e5e7eb;padding-top:16px;font-size:12px;color:#94a3b8;text-align:center">
        This report was generated automatically by your AI Email Assistant.
      </div>
    </td></tr>

  </table>
</td></tr>
</table>
</body></html>`;

return [{ json: {
  subject: `Daily AI Email Report - ${date}`, html,
  report_date: reportDate,
  total_emails: total, replied: replied, awaiting_approval: pending,
  rejected: n(r.rejected), owner_only: n(r.owner_only),
  bookings_made: n(r.bookings_made), bookings_rescheduled: n(r.bookings_rescheduled), bookings_cancelled: n(r.bookings_cancelled),
  errors: errors, by_category_json: JSON.stringify(cats)
} }];

const j = $input.first().json;
const e = j.execution || {};
const w = j.workflow || {};
const t = j.trigger || {};

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const wfName = w.name || 'Unknown workflow';
const failedNode = e.lastNodeExecuted || t.error?.node?.name || 'Unknown node';
const message = e.error?.message || t.error?.message || 'No error message';
const stack = String(e.error?.stack || t.error?.stack || '').split('\n').slice(0, 6).join('\n');
const execId = e.id || '-';
const execUrl = e.url || '';
const mode = e.mode || (t.error ? 'trigger' : '-');

const when = new Date().toLocaleString('en-GB', {
  timeZone: 'Asia/Dhaka', day: '2-digit', month: 'short', year: 'numeric',
  hour: '2-digit', minute: '2-digit', hour12: true
}) + ' (Dhaka)';

const row = (k, v) => `
  <tr>
    <td style="padding:10px 0;border-bottom:1px solid #f1f5f9;font-size:13px;color:#64748b;width:38%">${k}</td>
    <td style="padding:10px 0;border-bottom:1px solid #f1f5f9;font-size:14px;color:#0f172a;font-weight:600">${esc(v)}</td>
  </tr>`;

const button = execUrl
  ? `<tr><td style="padding:24px 32px 0">
       <a href="${esc(execUrl)}" style="display:inline-block;background:#dc2626;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:12px 22px;border-radius:8px">View execution</a>
     </td></tr>`
  : '';

const stackBlock = stack
  ? `<div style="margin-top:10px;font-family:Consolas,Monaco,monospace;font-size:11px;color:#64748b;white-space:pre-wrap">${esc(stack)}</div>`
  : '';

const html = `<!DOCTYPE html>
<html><body style="margin:0;padding:0;background:#f1f5f9">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:24px 0">
<tr><td align="center">
  <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;font-family:Arial,Helvetica,sans-serif">

    <tr><td style="background:#dc2626;padding:26px 32px">
